#!/usr/bin/env python3
"""채널 공개 캘린더 생성기: docs/채널-업로드로그.md → docs/채널-공개캘린더.html + .png
사용법: upload_calendar.py [--today YYYY-MM-DD]   (업로드 로그를 고칠 때마다 실행, 제7장 9-1)"""
import re, os, sys, json, datetime as dt, subprocess
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
LOG=f"{ROOT}/docs/채널-업로드로그.md"; OUT=f"{ROOT}/docs/채널-공개캘린더.html"; PNG=OUT[:-5]+".png"
today=dt.date.today().isoformat()
if "--today" in sys.argv: today=sys.argv[sys.argv.index("--today")+1]
main=[]; shorts={}; sec=None; strip=lambda t:t.strip().strip("*").strip()
for ln in open(LOG,encoding="utf-8"):
    if ln.startswith("## "): sec=ln; continue
    c=[strip(x) for x in ln.strip().strip("|").split("|")]
    if len(c)<4 or not re.match(r"\d{4}-\d{2}-\d{2}$",c[0]): continue
    if "본편" in sec:
        st={"공개":"pub","예약":"res","제안":"prop"}.get(c[2],"res")
        v=re.search(r"(\d[\d,]*)회",c[5]) if len(c)>5 else None
        main.append([c[0],st,c[3][:28],c[4] if len(c)>4 else "",int(v.group(1).replace(",","")) if v else None])
    elif "쇼츠" in sec:
        items=[]
        for part in re.split(r"\s/\s",c[3]):
            part=part.replace("— 공개","").strip()
            v=re.search(r"\((\d[\d,]*)회\)",part); name=re.sub(r"\(\d[\d,]*회\)","",part).strip()
            items.append([re.sub(r"\(제안\)","",name).strip()[:26], int(v.group(1).replace(",","")) if v else None, "제안" in part])
        shorts.setdefault(c[0],[]).extend(items)
months=sorted({(int(d[:4]),int(d[5:7])) for d in [m[0] for m in main]+list(shorts)})
head='<title>美談ものがたり 공개 캘린더</title>\n<meta name="claude:viewport-fit-sides" content="cover">\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Shippori+Mincho:wght@600;800&family=Noto+Sans+KR:wght@400;500;700&display=swap">\n<style>\n/* 레이아웃: 월간 7열 격자. 하루 칸에 본편(굵은 띠)·쇼츠(작은 칩)를 쌓는다. */\n:root{\n  --bg:#f6f3ec; --fg:#1f1b16; --muted:#6f6659; --line:#d9d2c4; --cell:#fffdf8;\n  --main-pub:#2b6e4f; --main-res:#b8641d; --main-prop:#8a1f2e;\n  --short:#5a6b8c; --short-bg:#e8edf6; --today:#fff2c2;\n  --display:"Shippori Mincho","Noto Serif CJK JP",serif; --body:"Noto Sans KR","Noto Sans CJK JP",system-ui,sans-serif;\n}\n@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){--bg:#17150f;--fg:#efe9dd;--muted:#a79d8b;--line:#3a352c;--cell:#211e17;--main-pub:#6fcf9a;--main-res:#f0a35a;--main-prop:#ff8a9a;--short:#b7c5e6;--short-bg:#2a3242;--today:#4a3f12;color-scheme:dark}}\n:root[data-theme="dark"]{--bg:#17150f;--fg:#efe9dd;--muted:#a79d8b;--line:#3a352c;--cell:#211e17;--main-pub:#6fcf9a;--main-res:#f0a35a;--main-prop:#ff8a9a;--short:#b7c5e6;--short-bg:#2a3242;--today:#4a3f12;color-scheme:dark}\nbody{background:var(--bg);color:var(--fg);font-family:var(--body);padding-block:24px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));}\n.wrap{max-width:1180px;margin:0 auto;display:grid;gap:20px}\nh1{font-family:var(--display);font-weight:800;font-size:clamp(22px,3vw,32px);margin:0;text-wrap:balance}\n.sub{color:var(--muted);font-size:14px;margin:4px 0 0}\n.legend{display:flex;flex-wrap:wrap;gap:10px 18px;font-size:13px;color:var(--muted)}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.sw{width:14px;height:14px;border-radius:3px;display:inline-block}\n.month h2{font-family:var(--display);font-size:20px;margin:0 0 8px}\n.grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px}\n.dow{text-align:center;font-size:12px;color:var(--muted);letter-spacing:.08em;padding:4px 0}\n.day{background:var(--cell);border:1px solid var(--line);border-radius:6px;min-height:92px;padding:6px;display:flex;flex-direction:column;gap:4px;min-width:0}\n.day.empty{background:transparent;border-color:transparent}\n.day.today{background:var(--today)}\n.num{font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums;display:flex;justify-content:space-between}\n.num b{color:var(--fg)}\n.main{font-size:12px;line-height:1.3;padding:4px 6px;border-radius:4px;color:#fff;font-weight:500;overflow-wrap:anywhere}\n.main.pub{background:var(--main-pub)} .main.res{background:var(--main-res)} .main.prop{background:var(--main-prop);outline:2px dashed var(--main-prop);outline-offset:1px}\n:root[data-theme="dark"] .main,:root:not([data-theme="light"]) .main{color:#111}\n@media (prefers-color-scheme: light){:root:not([data-theme="dark"]) .main{color:#fff}}\n:root[data-theme="light"] .main{color:#fff}\n.short{font-size:11px;line-height:1.3;padding:2px 5px;border-radius:3px;background:var(--short-bg);color:var(--short);overflow-wrap:anywhere}\n.short.prop{outline:1.5px dashed var(--main-prop);color:var(--main-prop)}\n.short .v{opacity:.75}\n.note{font-size:13px;color:var(--muted);line-height:1.6}\n.tbl{overflow-x:auto}\ntable{border-collapse:collapse;font-size:13px;min-width:520px;width:100%}\nth,td{text-align:left;padding:6px 8px;border-bottom:1px solid var(--line);vertical-align:top}\nth{color:var(--muted);font-weight:500;font-size:12px;letter-spacing:.06em}\ntd.n{font-variant-numeric:tabular-nums;text-align:right}\n@media (max-width:640px){.grid{gap:3px}.day{min-height:70px;padding:4px}.main{font-size:10px;padding:3px 4px}.short{font-size:9.5px;padding:2px 3px}.num{font-size:10px}}\n</style>\n<div class="wrap">\n  <header>\n    <h1>美談ものがたり 공개 캘린더</h1>\n    <p class="sub">YouTube 스튜디오 기준 2026-10-22 · 본편 9편(공개 5·예약 4) · 쇼츠 41편 · #03 『老舗旅館の嫁』 제안 일정 포함</p>\n  </header>\n  <div class="legend">\n    <span><i class="sw" style="background:var(--main-pub)"></i>본편 공개됨</span>\n    <span><i class="sw" style="background:var(--main-res)"></i>본편 예약됨</span>\n    <span><i class="sw" style="background:var(--main-prop)"></i>제안(미확정)</span>\n    <span><i class="sw" style="background:var(--short-bg);border:1px solid var(--short)"></i>쇼츠(숫자는 조회수)</span>\n    <span><i class="sw" style="background:var(--today)"></i>오늘</span>\n  </div>\n  <div id="cal"></div>\n  <div class="tbl">\n    <table>\n      <thead><tr><th>본편</th><th>날짜</th><th>상태</th><th>길이</th><th class="n">조회수</th></tr></thead>\n      <tbody id="list"></tbody>\n    </table>\n  </div>\n  <p class="note">본편 리듬은 금·화, 쇼츠는 거의 매일 1~2편. #03은 기예약 4편 뒤 첫 빈 금요일(11/6)에 두고, 쇼츠 5편은 기예약이 2편인 날(11/7)을 피해 11/8~11/12에 하루 1편씩 배치했습니다. 공개 시각은 전부 20:00 JST(쇼츠 평일 19:00·주말 12:00)로 가정했습니다.</p>\n</div>\n'
tail='const TODAY="2026-10-22", DOW=["월","화","수","목","금","토","일"];\nconst mainBy={}; MAIN.forEach(m=>mainBy[m[0]]=m);\nfunction month(y,m){\n  const first=new Date(y,m-1,1), days=new Date(y,m,0).getDate();\n  let lead=(first.getDay()+6)%7, h=`<section class="month"><h2>${y}년 ${m}월</h2><div class="grid">`;\n  h+=DOW.map(d=>`<div class="dow">${d}</div>`).join("");\n  for(let i=0;i<lead;i++)h+=`<div class="day empty"></div>`;\n  for(let d=1;d<=days;d++){\n    const k=`${y}-${String(m).padStart(2,"0")}-${String(d).padStart(2,"0")}`;\n    const mm=mainBy[k], ss=SHORTS[k]||[];\n    h+=`<div class="day${k===TODAY?" today":""}"><div class="num"><b>${d}</b>${mm?`<span>${mm[3]}</span>`:""}</div>`;\n    if(mm)h+=`<div class="main ${mm[1]}">${mm[2]}</div>`;\n    ss.forEach(s=>h+=`<div class="short${s[2]?" prop":""}">${s[0]}${s[1]!=null?` <span class="v">${s[1].toLocaleString()}</span>`:""}</div>`);\n    h+=`</div>`;\n  }\n  return h+`</div></section>`;\n}\ndocument.getElementById("cal").innerHTML=month(2026,10)+month(2026,11);\nconst st={pub:"공개",res:"예약",prop:"제안"};\ndocument.getElementById("list").innerHTML=MAIN.map(m=>{const d=new Date(m[0]);return `<tr><td>${m[2]}</td><td>${m[0].slice(5).replace("-","/")}(${DOW[(d.getDay()+6)%7]})</td><td>${st[m[1]]}</td><td>${m[3]}</td><td class="n">${m[4]==null?"–":m[4]}</td></tr>`}).join("");\n</script>\n'
tail=tail.replace("month(2026,10)+month(2026,11)","+".join(f"month({y},{m})" for y,m in months))
html=head+"<script>\nconst MAIN="+json.dumps(main,ensure_ascii=False)+";\nconst SHORTS="+json.dumps(shorts,ensure_ascii=False)+";\n"+tail.replace('const TODAY="2026-10-22"',f'const TODAY="{today}"')
html=re.sub(r'<p class="sub">.*?</p>',f'<p class="sub">업로드 로그 기준 {today} · 본편 {len(main)}편 · 쇼츠 {sum(len(v) for v in shorts.values())}편 · 주 2편(금·화) 리듬</p>',html,count=1)
open(OUT,"w",encoding="utf-8").write(html)
full=OUT+".full.html"; open(full,"w",encoding="utf-8").write('<!doctype html><html><head><meta charset="utf-8"></head><body style="margin:0">'+html+"</body></html>")
try:
    subprocess.run(["/opt/pw-browsers/chromium","--headless=new","--no-sandbox","--disable-gpu","--hide-scrollbars","--force-device-scale-factor=2","--window-size=1280,2400","--virtual-time-budget=4000",f"--screenshot={PNG}",f"file://{full}"],check=True,capture_output=True,timeout=120)
    from PIL import Image; im=Image.open(PNG); im.crop((0,0,im.width,min(im.height,3000))).save(PNG)
    print("PNG:",PNG)
except Exception as e: print("PNG 생략:",e)
finally: os.remove(full)
print("HTML:",OUT, "| 본편",len(main),"쇼츠",sum(len(v) for v in shorts.values()))
